  "dcontent_0_o2": "12",
  "dcontent_0_o3": "14",
  "dcontent_0_fact": "Les agriculteurs britanniques cultivent plus de 2 000 variétés de pommes — mais seulement 70 sortes environ sont vendues dans les magasins ! Les autres ont des noms géniaux comme « Bloody Ploughman » et « Slack-ma-Girdle ».",
  "dcontent_1_q": "Lequel de ces nombres est l'intrus — 2, 4, 7, 8 ?",
  "dcontent_1_o0": "2",
  "dcontent_1_o1": "4",
  "dcontent_1_o2": "7",
  "dcontent_1_o3": "8",
  "dcontent_1_fact": "Le 7 est le « chiffre préféré » le plus populaire au monde ! Plus de gens choisissent le 7 que n'importe quel autre chiffre. Personne ne sait vraiment pourquoi — les mathématiciens trouvent cela très étrange.",
  "dcontent_2_q": "Combien fait la moitié de 20 ?",
  "dcontent_2_o0": "5",
  "dcontent_2_o1": "8",
  "dcontent_2_o2": "10",
  "dcontent_2_o3": "15",
  "dcontent_2_fact": "Le mot « moitié » vient d'un mot vieux-français — ainsi, la moitié signifie littéralement une partie de quelque chose de divisé en deux égale. Nous utilisons ce concept mathématique depuis des millénaires !",
  "dcontent_3_q": "Combien font 7 × 8 ?",
  "dcontent_3_o0": "54",
  "dcontent_3_o1": "56",
  "dcontent_3_o2": "48",
  "dcontent_3_o3": "63",
  "dcontent_3_fact": "7 × 8 = 56, et 56 est ce qu'on appelle un « nombre pronique » — le produit de deux nombres consécutifs (7 et 8). Les mathématiciens ont donné des noms spéciaux à des milliers de types de nombres différents !",
  "dcontent_4_q": "Laquelle de ces fractions est la plus grande ?",
