  "dcontent_4_o2": "1/5",
  "dcontent_4_o3": "1/2",
  "dcontent_4_fact": "Les fractions étaient déjà utilisées dans l'Égypte ancienne il y a plus de 4 000 ans — mais les mathématiciens égyptiens n'utilisaient que des fractions avec un 1 au-dessus, comme 1/2 ou 1/3. Ils n'écrivaient jamais de fractions comme 3/4 !",
  "dcontent_5_q": "Un rectangle mesure 8 cm de long et 5 cm de large. Quelle est sa surface ?",
