  "dcontent_5_o3": "45 cm²",
  "dcontent_5_fact": "Les percepteurs d'impôts de la Rome antique utilisaient les mathématiques de surface pour calculer la propriété foncière et les factures d'impôts — les maths ont toujours eu un pouvoir concret !",
  "dcontent_6_q": "Quel mot rime avec « chat » ?",
