  "dcontent_7_fact": "Le mot « chat » a très peu changé au cours des siècles. « Selfie », quant à lui, n'est entré dans le dictionnaire qu'en 2013 !",
  "dcontent_8_q": "Combien de syllabes compte le mot « éléphant » ?",
  "dcontent_8_o0": "1",
