  "dcontent_8_o3": "4",
  "dcontent_8_fact": "Le mot « éléphant » vient d'un mot grec signifiant « ivoire » — car les défenses d'éléphant étaient la principale source d'ivoire dans le monde antique.",
  "dcontent_9_q": "Quelle est l'orthographe correcte ?",
