  "dcontent_14_o3": "hydrogène",
  "dcontent_14_fact": "Les arbres sont en partie faits d'air ! Ils absorbent le dioxyde de carbone et l'utilisent pour faire pousser leurs feuilles, leur tronc et leurs branches — l'air qui était autrefois dans les poumons de quelqu'un devient une partie d'un arbre !",
  "dcontent_15_q": "Pourquoi la glace flotte-t-elle sur l'eau au lieu de couler ?",
  "dcontent_15_o0": "Elle est plus légère que l'eau liquide",
