  "dcontent_15_o2": "Elle contient plus de sel",
  "dcontent_15_o3": "Elle est magnétique",
  "dcontent_15_fact": "L'eau est la seule substance courante dont la forme solide flotte sur la forme liquide — presque tout le reste coule quand ça gèle. Cette particularité de l'eau est l'une des raisons pour lesquelles la vie sur Terre peut exister !",
