  "dcontent_15_fact": "Woda to jedyna powszechna substancja, której postać stała pływa po ciekłej — prawie wszystko inne tonie, gdy zamarza. Ta niezwykła cecha wody to jeden z powodów, dla których na Ziemi mogło powstać życie!",
