  "article_reading_title": "ہفتے کا مطالعاتی مشورہ",
  "article_reading_p1": "تحقیق سے پتہ چلتا ہے کہ گھر میں روزانہ صرف 20 منٹ کا مطالعہ آپ کے بچے کی ترقی پر گہرا اثر ڈال سکتا ہے۔ وہ بچے جو اسکول کے باہر شوق سے مطالعہ کرتے ہیں، 11 سال کی عمر تک ان کے خواندگی کے اسکور نمایاں طور پر بہتر ہوتے ہیں۔",
  "article_reading_p2": "سب سے مؤثر چیزوں میں سے ایک یہ ہے کہ مل کر پڑھتے وقت کھلے سوالات پوچھیں۔ 'کیا آپ کو یہ پسند آیا؟' کے بجائے 'آپ کے خیال میں آگے کیا ہوگا؟' یا 'آپ کے خیال میں کردار نے ایسا کیوں کیا؟' پوچھنے کی کوشش کریں۔ یہ سوالات بیک وقت تفہیم اور تنقیدی سوچ کو فروغ دیتے ہیں۔",
  "article_reading_p3": "مطالعہ کے لیے سازگار ماحول بنائیں: اسکرین سے دور، قدرتی یا لیمپ کی اچھی روشنی والی آرام دہ جگہ۔ اپنے بچے کو وہ کتابیں منتخب کرنے دیں جن سے وہ لطف اندوز ہوں — یہاں تک کہ کامکس اور غیر افسانوی کتابیں بھی اہمیت رکھتی ہیں۔ لطف اندوزی مطالعہ میں بہتری کا سب سے بڑا پیش گو ہے۔",
  "article_reading_q1_q": "روزانہ کتنے منٹ مطالعہ کی سفارش کی جاتی ہے؟",
  "article_reading_q1_o0": "5 منٹ",
  "article_reading_q1_o1": "10 منٹ",
  "article_reading_q1_o2": "20 منٹ",
  "article_reading_q1_o3": "1 گھنٹہ",
  "article_reading_q2_q": "کس قسم کے سوالات فہم کو بہترین طریقے سے تیار کرتے ہیں؟",
  "article_reading_q2_o0": "ہاں/نہیں والے سوالات",
