  "tcontent_s1_name": "جولی راجر (The Jolly Roger)",
  "tcontent_s1_fact": "رائل نیوی میں آبدوزیں کامیاب مشن سے واپسی پر جولی راجر جھنڈا لہراتی ہیں! یہ روایت 1914 میں شروع ہوئی جب ایک ایڈمرل نے آبدوز کے عملے کو \"قزاقوں\" (pirates) کا نام دیا۔ ہر جھنڈے پر ایسی علامات ہوتی ہیں جو دکھاتی ہیں کہ آبدوز نے اپنے مشن پر کیا کیا۔",
  "tcontent_s1_location": "میوزیم کا داخلہ / ویلکم گیلری",
  "tcontent_s1_q": "رائل نیوی میں آبدوزوں کے جولی راجر جھنڈے لہرانے کی روایت کیسے شروع ہوئی؟",
