  "tcontent_s2_name": "ٹورپیڈو روم",
  "tcontent_s2_fact": "HMS Alliance کے اگلے حصے میں چار ٹورپیڈو ٹیوبیں ہیں۔ ایک ٹورپیڈو پانی کے ذریعے دشمن کے جہاز کو نشانہ بنانے کے لیے سفر کرتا ہے۔ جب مشن پر نہ ہوتے تو نو ملاح ٹورپیڈو کے بالکل ساتھ بستروں پر سوتے تھے — وہاں بمشکل جگہ ہوتی تھی!",
