  "tcontent_s3_name": "پیری اسکوپ (The Periscope)",
  "tcontent_s3_fact": "پیری اسکوپ 45 ڈگری کے زاویوں پر رکھے ہوئے آئینوں کا استعمال کرتا ہے تاکہ روشنی کو موڑ کر کونوں سے دکھا سکے۔ جب آبدوز سطح کے بالکل نیچے ہوتی ہے، تو کپتان آس پاس دیکھنے کے لیے پیری اسکوپ بلند کرتا ہے — لیکن صرف بہت تھوڑی دیر کے لیے، کیونکہ دشمن اسے پانی سے باہر نکلا ہوا دیکھ سکتا ہے!",
