  "tcontent_s4_fact": "ایک آبدوز بحری جہاز کی طرح رڈر (rudder) کی مدد سے دائیں اور بائیں مڑتی ہے۔ لیکن اسے پانی کے اندر اوپر اور نیچے جانے کی بھی ضرورت ہوتی ہے! یہ ہائیڈروپلینز (hydroplanes) نامی خصوصی پنکھوں کے ذریعے اور ٹینکوں کو پانی سے بھر کر ڈوبنے یا پانی باہر نکال کر اوپر اٹھنے کے ذریعے کیا جاتا ہے۔",
