  "tcontent_s5_name": "گیلی (باورچی خانہ)",
  "tcontent_s5_fact": "HMS Alliance کے باورچی کا کام آبدوز پر مشکل ترین کاموں میں سے ایک تھا — ایک چھوٹے سے باورچی خانے میں 65 افراد کے لیے دن میں تین وقت کا کھانا پکانا! ہر چیز کو مضبوطی سے باندھنا پڑتا تھا تاکہ آبدوز کے حرکت کرنے پر وہ اڑنے نہ لگے۔ عملے کو خوش رکھنے کے لیے گرم کھانا بہت ضروری تھا۔",
