  "tcontent_s6_fact": "HMS Alliance میں دو طرح کے انجن ہیں جو ایک ٹیم کے طور پر کام کرتے ہیں۔ سطح پر یہ بڑی بیٹریوں کو چارج کرنے کے لیے ڈیزل انجن استعمال کرتی ہے۔ جب یہ پانی کے اندر جاتی ہے تو خاموش الیکٹرک موٹروں پر منتقل ہو جاتی ہے — کیونکہ ڈیزل انجنوں کو کام کرنے کے لیے ہوا کی ضرورت ہوتی ہے، اور پانی کے اندر تازہ ہوا نہیں ہوتی!",
