  "tcontent_s7_name": "ہالینڈ I (Holland I)",
  "tcontent_s7_fact": "ہالینڈ I رائل نیوی کی سب سے پہلی آبدوز تھی، جو 1901 میں بنی تھی۔ اسے جان فلپ ہالینڈ نامی ایک آئرش-امریکی انجینئر نے ڈیزائن کیا تھا — جنہوں نے اصل میں برطانیہ کے خلاف لڑنے کے لیے آبدوز ایجاد کی تھی! یہ 1913 میں ڈوب گئی اور 70 سال بعد سمندر کی تہہ سے ملی۔",
  "tcontent_s7_location": "ہالینڈ I نمائش کی عمارت",
