  "tcontent_s8_fact": "X24 ایک اتنی چھوٹی آبدوز ہے کہ اس کے اندر صرف 4 ملاح سما سکتے تھے۔ 1944 میں یہ ناروے میں دشمن کی بندرگاہ میں ایک خفیہ مشن پر گئی اور دشمن کی آبدوزوں کی مرمت کرنے والی جرمن گودی کو تباہ کرنے کے لیے خصوصی چارجز استعمال کیے۔ عملہ ناقابل یقین حد تک بہادر تھا۔",
