  "lcontent_f001_title": "خشکی پر دنیا کی واحد آبدوز",
  "lcontent_f001_text": "HMS Alliance، جو 1945 میں بنی تھی، دوسری جنگ عظیم کے دور کی دنیا کی واحد برطانوی آبدوز ہے جو اب بھی خشکی پر محفوظ ہے۔ اس کا وزن 1,620 ٹن ہے اور یہ اگلے سرے سے پچھلے سرے تک 83 میٹر طویل ہے — ایک فٹ بال کے میدان سے بھی زیادہ لمبی! آپ یہاں Gosport میں رائل نیوی سب میرین میوزیم میں اس کے اندر جا سکتے ہیں۔",
  "lcontent_f001_location": "رائل نیوی سب میرین میوزیم، Gosport",
  "lcontent_f001_q": "رائل نیوی سب میرین میوزیم میں HMS Alliance کو کیا چیز خاص بناتی ہے؟",
  "lcontent_f001_oA": "یہ اب تک کی سب سے تیز رفتار آبدوز ہے",
  "lcontent_f001_oB": "یہ دوسری جنگ عظیم کے دور کی دنیا کی واحد برطانوی آبدوز ہے جو خشکی پر محفوظ ہے",
  "lcontent_f001_oC": "یہ دنیا کی پہلی آبدوز تھی",
  "lcontent_f001_oD": "اس نے بغیر رکے پوری دنیا کا سفر کیا",
  "lcontent_f002_title": "رائل ہسپتال ہیسلر (Haslar)",
  "lcontent_f002_text": "Gosport میں رائل ہسپتال ہیسلر برطانیہ کا پہلا مقصد کے لیے بنایا گیا بحری ہسپتال تھا، جو 1762 میں کھلا تھا۔ 200 سال سے زیادہ عرصے تک اس نے 100,000 سے زیادہ ملاحوں کی دیکھ بھال کی، جن میں 1805 میں ٹریفلگر کی جنگ میں زخمی ہونے والے مرد بھی شامل تھے۔ یہ بالآخر 2009 میں بطور ہسپتال بند ہوا — 247 سال کی خدمت کے بعد!",
  "lcontent_f002_location": "رائل ہسپتال ہیسلر، Gosport",
  "lcontent_f002_q": "رائل ہسپتال ہیسلر پہلی بار کس سال کھلا؟",
  "lcontent_f002_oA": "1642",
  "lcontent_f002_oB": "1762",
  "lcontent_f002_oC": "1862",
  "lcontent_f002_oD": "1962",
  "lcontent_f003_title": "برطانیہ کا ہور کرافٹ میوزیم",
  "lcontent_f003_text": "Lee-on-Solent میں ہور کرافٹ میوزیم، جو Gosport سے صرف 3 میل دور ہے، ہور کرافٹ کا دنیا کا سب سے بڑا مجموعہ رکھتا ہے۔ ایک ہور کرافٹ ہوا کی تہہ پر سفر کرتا ہے — طاقتور پنکھے ہوا کو نیچے کی طرف پھینکتے ہیں اور ایک ربڑ کا اسکرٹ اسے گاڑی کے نیچے قید کر لیتا ہے، جس سے یہ زمین سے اوپر اٹھ جاتی ہے۔ اس کا مطلب ہے کہ ہور کرافٹ پانی، کیچڑ اور زمین پر پھسل سکتا ہے!",
  "lcontent_f003_location": "ہور کرافٹ میوزیم، Lee-on-Solent (Gosport سے 3 میل دور)",
  "lcontent_f003_q": "ایک ہور کرافٹ زمین سے اوپر کیسے رہتا ہے؟",
  "lcontent_f003_oA": "یہ اچھلنے کے لیے بہت طاقتور پہیے استعمال کرتا ہے",
  "lcontent_f003_oB": "یہ ہیلی کاپٹر کی طرح گھومنے والے بلیڈز سے اڑتا ہے",
  "lcontent_f003_oC": "یہ ربڑ کے اسکرٹ کے ذریعے قید کی گئی ہوا کی تہہ پر تیرتا ہے",
  "lcontent_f003_oD": "یہ زمین سے دور دھکیلنے کے لیے مقناطیس استعمال کرتا ہے",
  "lcontent_f004_title": "Gosport فیری — 160 سال",
  "lcontent_f004_text": "Gosport فیری 1865 سے Gosport اور Portsmouth کے درمیان پانی کے مختصر فاصلے کو عبور کر رہی ہے — 160 سال سے زیادہ! یہ پورے برطانیہ میں پیدل مسافروں کی مصروف ترین فیری سروسز میں سے ایک ہے۔ یہ راستہ صرف 3 منٹ میں طے ہوتا ہے لیکن مسافروں کو بندرگاہ کے گرد 12 میل کی مسافت سے بچاتا ہے۔",
  "lcontent_f004_location": "Gosport فیری ٹرمینل، Gosport",
  "lcontent_f004_q": "Gosport فیری Gosport اور Portsmouth کے درمیان کتنے عرصے سے چل رہی ہے؟",
  "lcontent_f004_oA": "تقریباً 50 سال",
  "lcontent_f004_oB": "تقریباً 100 سال",
  "lcontent_f004_oC": "160 سال سے زیادہ",
  "lcontent_f004_oD": "300 سال سے زیادہ",
  "lcontent_f005_title": "Explosion! میوزیم",
  "lcontent_f005_text": "Gosport میں Priddy's Hard پر واقع Explosion! میوزیم میں رائل نیوی کے ہتھیاروں کی 300 سالہ تاریخ موجود ہے۔ Priddy's Hard کبھی بارود کا ایک خفیہ ذخیرہ تھا جہاں رائل نیوی کے جنگی جہازوں کو سپلائی کرنے کے لیے ہزاروں بیرل دھماکہ خیز مواد رکھا جاتا تھا۔ یہ اتنا خفیہ تھا کہ نقشوں پر بھی نظر نہیں آتا تھا! آج یہ ایک میوزیم ہے جہاں آپ بحری جنگ کی تاریخ دریافت کر سکتے ہیں۔",
  "lcontent_f005_location": "Explosion! میوزیم، Priddy's Hard، Gosport",
  "lcontent_f005_q": "Priddy's Hard اصل میں کس لیے استعمال ہوتا تھا؟",
  "lcontent_f005_oA": "رائل نیوی کے جنگی جہاز بنانے کے لیے",
  "lcontent_f005_oB": "رائل نیوی کے غوطہ خوروں کی تربیت کے لیے",
  "lcontent_f005_oC": "رائل نیوی کے لیے بارود اور دھماکہ خیز مواد ذخیرہ کرنے کے لیے",
  "lcontent_f005_oD": "ملاحوں کے لیے یونیفارم بنانے کے لیے",
  "lcontent_f006_title": "اسٹوکس بے (Stokes Bay) — ڈی-ڈے 1944",
  "lcontent_f006_text": "جون 1944 میں، انگلش چینل عبور کرنے کے لیے لینڈنگ کرافٹ پر سوار ہونے سے پہلے ہزاروں اتحادی فوجی Gosport کے اسٹوکس بے میں جمع ہوئے۔ یہ آپریشن اوور لارڈ (Operation Overlord) — ڈی-ڈے لینڈنگ — کا حصہ تھا جو تاریخ کا سب سے بڑا بحری حملہ تھا۔ یہ دوسری جنگ عظیم میں ایک اہم موڑ تھا اور اس نے نازی جرمنی کو شکست دینے میں مدد کی۔ اسٹوکس بے کا ساحل آج پرسکون نظر آتا ہے، لیکن یہ جدید تاریخ کے اہم ترین لمحات میں سے ایک کا گواہ رہا ہے۔",
  "lcontent_f006_location": "اسٹوکس بے، Gosport",
  "lcontent_f006_q": "Gosport میں اسٹوکس بے سے دوسری جنگ عظیم کا کون سا بڑا آپریشن شروع ہوا؟",
  "lcontent_f006_oA": "برطانیہ کی جنگ (The Battle of Britain)",
