  "dcontent_0_q": "اگر آپ کے پاس 3 تھیلے ہیں اور ہر تھیلے میں 4 سیب ہیں، تو آپ کے پاس کل کتنے سیب ہیں؟",
  "dcontent_0_o0": "8",
