  "dcontent_0_fact": "برطانیہ میں کسان سیب کی 2,000 سے زیادہ اقسام اگاتے ہیں — لیکن دکانوں میں صرف 70 کے قریب قسمیں بیچی جاتی ہیں! باقی کے نام بہت دلچسپ ہیں جیسے \"Bloody Ploughman\" اور \"Slack-ma-Girdle\"۔",
  "dcontent_1_q": "ان نمبروں میں سے کون سا مختلف ہے — 2، 4، 7، 8؟",
