  "dcontent_1_fact": "7 دنیا کا سب سے مقبول \"پسندیدہ نمبر\" ہے! کسی بھی دوسرے نمبر کے مقابلے میں زیادہ لوگ 7 کا انتخاب کرتے ہیں۔ کوئی بھی یقین سے نہیں جانتا کہ ایسا کیوں ہے — ریاضی دانوں کو یہ بہت عجیب لگتا ہے۔",
  "dcontent_2_q": "20 کا آدھا کیا ہے؟",
