  "dcontent_2_fact": "لفظ \"آدھا\" (half) ایک قدیم انگریزی لفظ سے آیا ہے جس کا مطلب ہے \"طرف\" (side) — اس لیے آدھے کا لغوی مطلب ہے دو حصوں میں تقسیم ہونے والی کسی چیز کا ایک رخ۔ انگریزی 1,000 سال سے زائد عرصے سے یہ لفظ استعمال کر رہی ہے!",
