  "dcontent_3_fact": "7 × 8 = 56، اور 56 کو \"پرونک نمبر\" (pronic number) کہا جاتا ہے — یہ دو مسلسل نمبروں (7 اور 8) کا حاصل ضرب ہے۔ ریاضی دانوں نے ہزاروں مختلف اقسام کے نمبروں کو خصوصی نام دے رکھے ہیں!",
