  "dcontent_4_fact": "قدیم مصر میں 4,000 سال پہلے کسریں استعمال ہوتی تھیں — لیکن مصری ریاضی دان ہمیشہ صرف وہ کسریں استعمال کرتے تھے جن کے اوپر 1 ہوتا تھا، جیسے 1/2 یا 1/3۔ انہوں نے کبھی 3/4 جیسی کسریں نہیں لکھیں!",
  "dcontent_5_q": "ایک مستطیل 8 سینٹی میٹر لمبا اور 5 سینٹی میٹر چوڑا ہے۔ اس کا رقبہ کیا ہے؟",
