  "dcontent_13_fact": "اگرچہ عطارد سورج کے قریب ترین ہے، لیکن یہ سب سے گرم سیارہ نہیں ہے — وینس ہے! وینس کا ایک گاڑھا ماحول ہے جو گرمی کو کمبل کی طرح قید کر لیتا ہے۔ عطارد کا تقریباً کوئی ماحول نہیں ہے۔",
