  "dcontent_21_fact": "بحر اوقیانوس ہر سال تقریباً 2.5 سینٹی میٹر چوڑا ہوتا ہے — تقریباً اتنی ہی رفتار سے جتنی آپ کے ناخن بڑھتے ہیں۔ 100 ملین سالوں میں یہ دوگنا چوڑا ہو جائے گا!",
  "dcontent_22_q": "رقبے کے لحاظ سے دنیا کا سب سے بڑا ملک کون سا ہے؟",
  "dcontent_22_o0": "چین",
  "dcontent_22_o1": "امریکہ",
  "dcontent_22_o2": "کینیڈا",
  "dcontent_22_o3": "روس",
  "dcontent_22_fact": "روس اتنا بڑا ہے کہ یہ 11 مختلف ٹائم زونز پر پھیلا ہوا ہے — جب روس کے ایک حصے میں آدھی رات ہوتی ہے، تو دوسرے حصے میں اگلے دن کے صبح کے 11 بج رہے ہوتے ہیں!",
  "dcontent_23_q": "ان میں سے کون سا قابل تجدید توانائی (renewable energy) کا ذریعہ ہے؟",
