  "dcontent_23_o1": "قدرتی گیس",
  "dcontent_23_o2": "ہوا (wind)",
  "dcontent_23_o3": "تیل",
  "dcontent_23_fact": "بہت زیادہ ہوا والے دنوں میں، برطانیہ کی ونڈ ٹربائنز کبھی کبھی اتنی بجلی پیدا کرتی ہیں جتنی اس وقت پورے ملک کی ضرورت نہیں ہوتی — فالتو بجلی کو اسٹور کرنا پڑتا ہے یا پڑوسی ممالک کے ساتھ شیئر کرنا پڑتا ہے!",
  "dcontent_24_q": "قوس و قزح (rainbow) میں کتنے رنگ ہوتے ہیں؟",
