  "dcontent_24_o1": "6",
  "dcontent_24_o2": "7",
  "dcontent_24_o3": "8",
  "dcontent_24_fact": "شہد کی مکھیاں الٹرا وائلٹ روشنی دیکھ سکتی ہیں — ایسا رنگ جو انسان بالکل نہیں دیکھ سکتے! پھولوں میں الٹرا وائلٹ میں چھپے ہوئے پیٹرن اور رنگ ہوتے ہیں جنہیں صرف مکھیاں اور کچھ دوسرے حشرات دیکھ سکتے ہیں۔",
  "dcontent_25_q": "ایک ساتھ تیرنے والی مچھلیوں کے گروپ کو کیا کہتے ہیں؟",
  "dcontent_25_o0": "پیک (pack)",
  "dcontent_25_o1": "فلاک (flock)",
  "dcontent_25_o2": "شول (shoal)",
  "dcontent_25_o3": "ہرڈ (herd)",
  "dcontent_25_fact": "مچھلیاں ایک سیکنڈ کے حصے میں ایک ساتھ مڑ سکتی ہیں کیونکہ ان کا ایک خاص عضو ہوتا ہے جسے \"لیٹرل لائن\" (lateral line) کہتے ہیں جو ان کے اطراف میں ہوتا ہے اور قریبی مچھلیوں سے پانی میں ہونے والی تھرتھراہٹ کو محسوس کرتا ہے!",
  "dcontent_26_q": "ان میں سے کون سا مختلف ہے: مثلث، دائرہ، مربع، مکعب (cube)؟",
  "dcontent_26_o0": "مثلث",
  "dcontent_26_o1": "دائرہ",
  "dcontent_26_o2": "مربع",
  "dcontent_26_o3": "مکعب",
  "dcontent_26_fact": "کسی بھی 3D شکل کے لیے، اگر آپ سطحوں (faces) کو گنیں، کونوں (vertices) کو جمع کریں، پھر کناروں (edges) کو تفریق کریں، تو جواب ہمیشہ 2 آتا ہے۔ یہ دریافت لیونارڈ اویلر نامی سوئس ریاضی دان نے کی تھی!",
  "dcontent_27_q": "ورلڈ وائیڈ ویب (World Wide Web) کس نے ایجاد کیا؟",
