  "dcontent_27_o1": "اسٹیو جابز",
  "dcontent_27_o2": "سر ٹم برنرز لی",
  "dcontent_27_o3": "ایلن ٹیورنگ",
  "dcontent_27_fact": "سر ٹم برنرز لی نے 1989 میں ورلڈ وائیڈ ویب ایجاد کیا اور اسے دنیا کو مفت دے دیا — ان کی سخاوت کے بغیر، انٹرنیٹ جیسا کہ ہم آج جانتے ہیں کسی نجی کمپنی کی ملکیت ہو سکتا تھا!",
  "dcontent_28_q": "ان میں سے قدیم ترین کون سا ہے: ایفل ٹاور، دیوارِ چین، سٹون ہینج (Stonehenge)، یا بگ بین؟",
  "dcontent_28_o0": "ایفل ٹاور",
  "dcontent_28_o1": "دیوارِ چین",
  "dcontent_28_o2": "سٹون ہینج",
  "dcontent_28_o3": "بگ بین",
  "dcontent_28_fact": "سٹون ہینج تقریباً 5,000 سال پرانا ہے — یہ تب بھی قدیم تھا جب گیزہ کا عظیم اہرام بنایا گیا تھا، اور جب اس کے بنانے والوں نے اپنا کام مکمل کیا تھا تب رومی ابھی پیدا بھی نہیں ہوئے تھے!",
  "dcontent_29_q": "لندن میں پارلیمنٹ ہاؤس کے مشہور کلاک ٹاور کا اصل نام کیا ہے؟",
