  "dcontent_29_fact": "اصل \"بگ بین\" ٹاور نہیں ہے — یہ اس کے اندر موجود 13.7 ٹن وزنی گھڑیال ہے! ٹاور کا نام 2012 میں ملکہ الزبتھ دوم کی ڈائمنڈ جوبلی کے اعزاز میں تبدیل کر کے الزبتھ ٹاور رکھ دیا گیا تھا۔"
