  "article_reading_title": "Haftanın Okuma İpucu",
  "article_reading_p1": "Araştırmalar, evde yapılan günlük sadece 20 dakikalık okumanın çocuğunuzun gelişimi üzerinde çarpıcı bir etkisi olabileceğini gösteriyor. Okul dışında zevk için kitap okuyan çocukların 11 yaşına geldiklerinde okuma-yazma puanları önemli ölçüde daha yüksek olmaktadır.",
  "article_reading_p2": "Yapabileceğiniz en etkili şeylerden biri, birlikte okurken açık uçlu sorular sormaktır. 'Bunu beğendin mi?' yerine 'Sence bir sonraki adımda ne olacak?' veya 'Sence karakter neden böyle yaptı?' gibi soruları deneyin. Bu sorular aynı zamanda anlama ve eleştirel düşünme becerilerini geliştirir.",
  "article_reading_p3": "Okumaya uygun bir ortam oluşturun: Ekranlardan uzak, doğal ışık alan veya lamba ile iyi aydınlatılmış rahat bir köşe. Çocuğunuzun keyif aldığı kitapları seçmesine izin verin; çizgi romanlar ve kurgu dışı kitaplar da buna dahildir. Keyif almak, okuma becerisindeki gelişimin en büyük göstergesidir.",
  "article_reading_q1_q": "Günlük kaç dakika okuma yapılması önerilir?",
  "article_reading_q1_o0": "5 dk",
  "article_reading_q1_o1": "10 dk",
  "article_reading_q1_o2": "20 dk",
  "article_reading_q1_o3": "1 saat",
  "article_reading_q2_q": "Anlamayı en iyi ne tür sorular geliştirir?",
  "article_reading_q2_o0": "Evet/Hayır soruları",
  "article_reading_q2_o1": "Heceleme soruları",
  "article_reading_q2_o2": "Açık uçlu sorular",
  "article_reading_q2_o3": "Çarpım tabloları",
  "article_reading_q3_q": "Okuma gelişiminin en büyük göstergesi nedir?",
  "article_reading_q3_o0": "Kitabın uzunluğu",
  "article_reading_q3_o1": "Keyif almak",
  "article_reading_q3_o2": "Okuma hızı",
