  "tcontent_s1_name": "Jolly Roger",
  "tcontent_s1_fact": "Kraliyet Donanması'ndaki denizaltılar, başarılı bir görevden döndüklerinde Jolly Roger bayrağı çekerler! Bu gelenek 1914 yılında bir Amiralin denizaltıcıları \"korsanlar\" olarak adlandırmasıyla başladı. Her bayrak, denizaltının görevinde ne yaptığını gösteren semboller taşır.",
  "tcontent_s1_location": "Müze Girişi / Karşılama Galerisi",
  "tcontent_s1_q": "Kraliyet Donanması denizaltılarının Jolly Roger bayrağı çekme geleneğini ne başlattı?",
