  "tcontent_s1_o2": "Bir denizcinin hazine haritası bulması",
  "tcontent_s2_name": "Torpido Odası",
  "tcontent_s2_fact": "HMS Alliance'ın ön kısmında dört adet torpido kovanı bulunmaktadır. Bir torpido, düşman gemisini vurmak için suyun içinde yol alır. Görevde olmadıklarında, dokuz denizci torpidoların hemen yanındaki ranzalarda uyurdu — neredeyse hiç yer yoktu!",
  "tcontent_s2_location": "HMS Alliance — Ön Bölme",
