  "tcontent_s3_name": "Periskop",
  "tcontent_s3_fact": "Periskop, ışığı köşelerden bükmek için 45 derecelik açılarla yerleştirilmiş aynalar kullanır. Denizaltı suyun hemen altındayken, kaptan etrafa bakmak için periskobu kaldırır — ama sadece çok kısa bir süre için, çünkü düşman suyun dışına çıkan periskobu fark edebilir!",
  "tcontent_s3_location": "HMS Alliance — Kontrol Odası / Kule",
  "tcontent_s3_q": "Kaptan suyun üzerini görebilsin diye bir periskop ışığı bükmek için ne kullanır?",
