  "tcontent_s3_o2": "Bir kamera",
  "tcontent_s4_name": "Dümen",
  "tcontent_s4_fact": "Bir denizaltı, tıpkı bir gemi gibi dümen kullanarak sağa ve sola döner. Ancak su altında yukarı ve aşağı da gitmesi gerekir! Bunu su kanatları (hidroplan) adı verilen özel kanatçıklar kullanarak ve batmak için tankları suyla doldurarak veya yükselmek için suyu dışarı pompalayarak yapar.",
  "tcontent_s4_location": "HMS Alliance — Kontrol Odası",
  "tcontent_s4_q": "Bir denizaltının ne kadar derine gideceğini kontrol eden kanatçıklara ne ad verilir?",
