  "tcontent_s4_o1": "Su kanatları (Hidroplanlar)",
  "tcontent_s4_o2": "Stabilizatörler",
  "tcontent_s5_name": "Kuzine (Mutfak)",
  "tcontent_s5_fact": "HMS Alliance'daki aşçı denizaltındaki en zor işlerden birine sahipti — küçücük bir mutfakta 65 kişi için günde üç öğün yemek pişirmek! Denizaltı hareket ettiğinde etrafa uçmasınlar diye her şeyin sabitlenmesi gerekiyordu. Sıcak yemek, mürettebatı mutlu etmek için çok önemliydi.",
  "tcontent_s5_location": "HMS Alliance — Orta Kısım",
