  "tcontent_s6_name": "Makine Dairesi",
  "tcontent_s6_fact": "HMS Alliance, takım olarak çalışan iki tip motora sahiptir. Su yüzeyindeyken devasa pilleri şarj etmek için dizel motor kullanır. Suyun altına daldığında ise sessiz elektrik motorlarına geçer — çünkü dizel motorlar çalışmak için havaya ihtiyaç duyar ve su altında taze hava yoktur!",
