  "tcontent_s7_name": "Holland I",
  "tcontent_s7_fact": "Holland I, Kraliyet Donanması'nın 1901 yılında inşa edilen ilk denizaltısıydı. John Philip Holland adında İrlanda asıllı Amerikalı bir mühendis tarafından tasarlandı — kendisi aslen denizaltıyı Britanya'ya karşı savaşmak için icat etmişti! 1913 yılında battı ve 70 yıl sonra deniz yatağında bulundu.",
  "tcontent_s7_location": "Holland I Sergi Binası",
  "tcontent_s7_q": "Kraliyet Donanması'nın ilk denizaltısı olan Holland I'i kim tasarladı?",
  "tcontent_s7_o0": "Bir İngiliz donanma mühendisi",
  "tcontent_s7_o1": "John Philip Holland — İrlanda asıllı Amerikalı bir mühendis",
  "tcontent_s7_o2": "Bir Alman mühendis",
  "tcontent_s8_name": "X24 Cüce Denizaltı",
  "tcontent_s8_fact": "X24, içine sadece 4 denizcinin sığabileceği kadar küçük bir cüce denizaltıdır. 1944 yılında Norveç'teki bir düşman limanına gizli bir göreve gitti ve düşman denizaltılarını onaran bir Alman rıhtımını yok etmek için özel patlayıcılar kullandı. Mürettebat inanılmaz derecede cesurdu.",
  "tcontent_s8_location": "Ana Müze Galerisi — Sessiz ve Gizli",
