  "lcontent_f001_title": "Dünyanın Karadaki Tek Denizaltısı",
  "lcontent_f001_text": "1945'te inşa edilen HMS Alliance, dünyada hala karada korunan tek sağlam II. Dünya Savaşı dönemi İngiliz denizaltısıdır. 1.620 ton ağırlığındadır ve başından kıçına 83 metre uzanır — bir futbol sahasından daha uzundur! Gosport'taki Kraliyet Donanması Denizaltı Müzesi'nde içini gezebilirsiniz.",
  "lcontent_f001_location": "Kraliyet Donanması Denizaltı Müzesi, Gosport",
