  "lcontent_f002_title": "Kraliyet Haslar Hastanesi",
  "lcontent_f002_text": "Gosport'taki Kraliyet Haslar Hastanesi, İngiltere'nin amaca yönelik olarak inşa edilen ilk donanma hastanesidir ve 1762 yılında kapılarını açmıştır. 200 yılı aşkın bir süre boyunca, 1805'teki Trafalgar Savaşı'nda yaralananlar da dahil olmak üzere 100.000'den fazla denizciye bakım hizmeti vermiştir. 247 yıllık hizmetin ardından nihayet 2009 yılında hastane olarak kapanmıştır!",
  "lcontent_f002_location": "Kraliyet Haslar Hastanesi, Gosport",
