  "lcontent_f003_title": "Britanya Hovercraft Müzesi",
  "lcontent_f003_text": "Gosport'a sadece 3 mil uzaklıktaki Lee-on-Solent'te bulunan Hovercraft Müzesi, dünyanın en büyük hovercraft koleksiyonuna ev sahipliği yapmaktadır. Bir hovercraft hava yastığı üzerinde hareket eder — güçlü fanlar havayı aşağı doğru üfler ve bir lastik etek bu havayı aracın altında hapsederek onu yerden yükseltir. Bu, bir hovercraft'ın su, çamur ve kara üzerinde kayabileceği anlamına gelir!",
  "lcontent_f003_location": "Hovercraft Müzesi, Lee-on-Solent (Gosport'a 3 mil)",
