  "lcontent_f004_title": "Gosport Feribotu — 160 Yıl",
  "lcontent_f004_text": "Gosport Feribotu, 1865'ten bu yana Gosport ve Portsmouth arasındaki kısa su yolunu geçmektedir — 160 yılı aşkın bir süredir! Tüm Birleşik Krallık'taki en yoğun yaya yolcu feribot seferlerinden biridir. Geçiş sadece 3 dakika sürer ancak yolcuları limanın etrafından dolaşan 12 millik bir sürüşten kurtarır.",
  "lcontent_f004_location": "Gosport Feribot Terminali, Gosport",
  "lcontent_f004_q": "Gosport Feribotu ne kadar süredir Gosport ve Portsmouth arasında çalışmaktadır?",
