  "lcontent_f004_oC": "160 yılı aşkın süredir",
  "lcontent_f004_oD": "300 yılı aşkın süredir",
  "lcontent_f005_title": "Explosion! Müzesi",
  "lcontent_f005_text": "Gosport, Priddy's Hard'da bulunan Explosion! Müzesi, 300 yıllık Kraliyet Donanması silah tarihine sahiptir. Priddy's Hard, bir zamanlar Kraliyet Donanması savaş gemilerine tedarik sağlamak için binlerce varil patlayıcının saklandığı gizli bir barut deposuydu. O kadar gizliydi ki haritalarda görünmüyordu! Bugün ise deniz savaşı tarihini keşfedebileceğiniz bir müzedir.",
  "lcontent_f005_location": "Explosion! Müzesi, Priddy's Hard, Gosport",
  "lcontent_f005_q": "Priddy's Hard başlangıçta ne için kullanılıyordu?",
  "lcontent_f005_oA": "Kraliyet Donanması savaş gemilerini inşa etmek",
  "lcontent_f005_oB": "Kraliyet Donanması dalgıçlarını eğitmek",
  "lcontent_f005_oC": "Kraliyet Donanması için barut ve patlayıcı depolamak",
  "lcontent_f005_oD": "Denizciler için üniforma yapmak",
  "lcontent_f006_title": "Stokes Bay — D-Day 1944",
  "lcontent_f006_text": "Haziran 1944'te binlerce müttefik askeri, Manş Denizi'ni geçmek üzere çıkarma araçlarına binmeden önce Gosport'taki Stokes Bay'de toplandı. Bu, tarihin en büyük deniz istilası olan Overlord Operasyonu — D-Day çıkarmalarının — bir parçasıydı. İkinci Dünya Savaşı'nda bir dönüm noktasıydı ve Nazi Almanyası'nın yenilgiye uğratılmasına yardımcı oldu. Stokes Bay'deki plaj bugün huzurlu görünüyor ancak modern tarihin en önemli anlarından birine tanıklık etti.",
  "lcontent_f006_location": "Stokes Bay, Gosport",
  "lcontent_f006_q": "Gosport'taki Stokes Bay'den hangi büyük II. Dünya Savaşı operasyonu başlatıldı?",
  "lcontent_f006_oA": "Britanya Savaşı",
  "lcontent_f006_oB": "Overlord Operasyonu — D-Day çıkarmaları",
  "lcontent_f006_oC": "Dunkirk tahliyesi",
  "lcontent_f006_oD": "Atlantik Savaşı",
  "dcontent_0_q": "Eğer içinde 4 elma olan 3 torban varsa, toplamda kaç elman olur?",
  "dcontent_0_o0": "8",
  "dcontent_0_o1": "10",
  "dcontent_0_o2": "12",
  "dcontent_0_o3": "14",
  "dcontent_0_fact": "İngiltere'deki çiftçiler 2.000'den fazla elma çeşidi yetiştiriyor — ancak dükkanlarda sadece yaklaşık 70 çeşidi satılıyor! Geri kalanların \"Bloody Ploughman\" (Kanlı Çiftçi) ve \"Slack-ma-Girdle\" gibi harika isimleri var.",
  "dcontent_1_q": "Bu sayılardan hangisi farklıdır — 2, 4, 7, 8?",
  "dcontent_1_o0": "2",
  "dcontent_1_o1": "4",
  "dcontent_1_o2": "7",
  "dcontent_1_o3": "8",
  "dcontent_1_fact": "7, dünyadaki en popüler \"en sevilen sayı\"dır! Diğer tüm sayılardan daha fazla kişi 7'yi seçiyor. Kimse nedeninden tam olarak emin değil — matematikçiler bunu çok tuhaf buluyor.",
  "dcontent_2_q": "20'nin yarısı kaçtır?",
  "dcontent_2_o0": "5",
  "dcontent_2_o1": "8",
  "dcontent_2_o2": "10",
  "dcontent_2_o3": "15",
  "dcontent_2_fact": "\"Half\" (Yarım) kelimesi, Eski İngilizce'de \"taraf\" anlamına gelen bir kelimeden gelir — yani yarım, kelimenin tam anlamıyla ikiye bölünmüş bir şeyin bir tarafı demektir. İngilizce bu kelimeyi 1.000 yılı aşkın süredir kullanıyor!",
  "dcontent_3_q": "7 × 8 kaçtır?",
  "dcontent_3_o0": "54",
  "dcontent_3_o1": "56",
  "dcontent_3_o2": "48",
  "dcontent_3_o3": "63",
  "dcontent_3_fact": "7 × 8 = 56'dır ve 56'ya \"pronic sayı\" (ardışık iki sayının çarpımı olan sayı, 7 ve 8 gibi) denir. Matematikçiler binlerce farklı sayı türüne özel isimler vermiştir!",
  "dcontent_4_q": "Bu kesirlerden hangisi en büyüktür?",
  "dcontent_4_o0": "1/3",
  "dcontent_4_o1": "1/4",
  "dcontent_4_o2": "1/5",
  "dcontent_4_o3": "1/2",
  "dcontent_4_fact": "Kesirler 4.000 yılı aşkın bir süre önce Antik Mısır'da kullanılıyordu — ancak Mısırlı matematikçiler sadece üstünde 1 olan 1/2 veya 1/3 gibi kesirleri kullandılar. Asla 3/4 gibi kesirler yazmadılar!",
  "dcontent_5_q": "Bir dikdörtgen 8 cm uzunluğunda ve 5 cm genişliğindedir. Alanı nedir?",
  "dcontent_5_o0": "13cm²",
  "dcontent_5_o1": "26cm²",
  "dcontent_5_o2": "40cm²",
  "dcontent_5_o3": "45cm²",
  "dcontent_5_fact": "Antik Roma vergi memurları, arazi mülkiyetini ve vergi faturalarını hesaplamak için alan matematiğini kullandılar — matematik her zaman gerçek dünya gücüne sahip olmuştur!",
  "dcontent_6_q": "Hangi kelime \"cat\" ile kafiyelidir?",
  "dcontent_6_o0": "dog",
  "dcontent_6_o1": "bat",
  "dcontent_6_o2": "fish",
  "dcontent_6_o3": "sun",
  "dcontent_6_fact": "İngilizce, hemen hemen diğer tüm dillerden daha fazla kafiyeli kelimeye sahiptir — İngiliz çocuk tekerlemelerinin ve şiirlerinin bu kadar zengin olmasının bir nedeni de budur!",
  "dcontent_7_q": "Bunlardan hangisi bir isimdir — run, beautiful, cat, quickly?",
  "dcontent_7_o0": "run",
  "dcontent_7_o1": "beautiful",
  "dcontent_7_o2": "cat",
  "dcontent_7_o3": "quickly",
  "dcontent_7_fact": "\"Cat\" (Kedi) kelimesi İngilizcede 1.000 yılı aşkın süredir neredeyse hiç değişmedi. Öte yandan \"Selfie\" kelimesi sözlüğe sadece 2013 yılında girdi!",
  "dcontent_8_q": "\"Elephant\" kelimesi kaç hecedir?",
  "dcontent_8_o0": "1",
  "dcontent_8_o1": "2",
  "dcontent_8_o2": "3",
  "dcontent_8_o3": "4",
  "dcontent_8_fact": "\"Elephant\" (Fil) kelimesi, Yunanca \"fildişi\" anlamına gelen bir kelimeden gelir — çünkü antik dünyada fildişinin ana kaynağı fil dişleriydi.",
  "dcontent_9_q": "Hangi yazım doğrudur?",
  "dcontent_9_o0": "Beutiful",
  "dcontent_9_o1": "Beautifull",
  "dcontent_9_o2": "Beautiful",
  "dcontent_9_o3": "Beautifall",
  "dcontent_9_fact": "Kullanışlı bir hafıza taktiği: \"Big Elephants Are Usually Tiny If For Underdogs Love\" cümlesini düşünün — kelimelerin ilk harfleri B-E-A-U-T-I-F-U-L'ı oluşturur!",
  "dcontent_10_q": "\"She ran quickly to school\" cümlesinde \"quickly\" kelimesi ne tür bir kelimedir?",
