  "dcontent_10_o1": "sıfat",
  "dcontent_10_o2": "fiil",
  "dcontent_10_o3": "zarf",
  "dcontent_10_fact": "Zarflar yapmak için kullanılan \"-ly\" eki, Eski İngilizce'de \"... tarzında\" anlamına gelen \"-lice\" ekinden gelir — 1.200 yılı aşkın bir süredir İngilizcenin bir parçasıdır.",
  "dcontent_11_q": "Nokta kullanmadan birbiriyle ilişkili iki cümleyi hangi noktalama işareti birleştirir?",
