  "dcontent_11_o1": "iki nokta",
  "dcontent_11_o2": "noktalı virgül",
  "dcontent_11_o3": "tire",
  "dcontent_11_fact": "Noktalı virgül, basılı eserlerde ilk kez 1494 yılında Venedik'te dahi İtalyan matbaacı Aldus Manutius tarafından kullanıldı — aynı zamanda italik yazı tipini ve cep boy kitabı icat eden kişi!",
  "dcontent_12_q": "Aşağıdakilerden hangisi bir memelidir?",
