  "dcontent_12_o1": "japon balığı",
  "dcontent_12_o2": "kartal",
  "dcontent_12_o3": "yunus",
  "dcontent_12_fact": "Yunuslar o kadar zekidirler ki birbirlerine isim verdikleri gözlemlenmiştir — her yunusun bir isim gibi işlev gören kendine özgü bir ıslığı vardır ve diğer yunuslar onların dikkatini çekmek için bunu kullanır!",
