  "acontent_d_story_time_creator_desc": "Isticmaal dhiirigelinta hoose si aad u dhistaan sheeko gaaban oo wadajir ah — sheekadaada waxaa lagu keydiyaa gudaha.",
  "acontent_d_random_kindness_title": "Ficil naxariis leh oo aan qorshaysnayn",
  "acontent_d_random_kindness_desc": "Ilmahaagu wuxuu u sameeyaa ficil naxariis leh qof kale — halkan ku sharax oo labadiinuba xaqiijiya.",
  "acontent_d_teach_the_parent_title": "Bar Waalidka",
  "acontent_d_teach_the_parent_desc": "Ilmahaagu wuxuu doortaa mowduuc wuxuuna ku barayaa adiga — ka qiimee sharaxaadooda 1 illaa 5.",
  "acontent_d_family_values_title": "Wadahadalka Qiyamka Qoyska",
  "acontent_d_family_values_desc": "Mowduuca toddobaadkan: ka wadahadla waxa ay dacadnimadu ka dhigan tahay oo la wadaaga tusaale dhab ah oo ka yimid noloshaada.",
  "acontent_d_world_food_night_title": "Habeenka Cuntada Adduunka",
  "acontent_d_world_food_night_desc": "Wada kariya cunto laga helo waddanka la doonayay oo akhriya macluumaadka waddanka ee hoose.",
  "acontent_d_language_phrases_title": "Caqabadda Ereyada Luqadda",
  "acontent_d_language_phrases_desc": "Wada barta 5 erey oo Faransiis ah adigoo isticmaalaya hagaha dhawaaqista — ku tababbarta ilaa aad labadiinuba kalsooni ka heshaan.",
  "acontent_d_history_detective_title": "Baadhaha Taariikhda",
  "acontent_d_history_detective_desc": "Wada akhriya tilmaamaha oo xalli qarsoodiga taariikhiga ah ka hor inta aan jawaabta la shaacin.",
